  const safety = machine.safetyRules && machine.safetyRules.length > 0
    ? checkSafetyRules(conformance.observations, machine.safetyRules)
    : { ok: true, violations: [] };

  return {
    name: machine.name,
    ok: completeness.ok && liveness.ok && conformance.ok && safety.ok,
    completeness,
    liveness,
    conformance,
    safety,
  };
